        if ((flags & 2) != 0)
            message.SlidingTicks = reader.Signed();
        if ((flags & 4) != 0)
            message.OperationId = reader.OperationId();
        if ((flags & 8) != 0)
            message.TtlTicks = reader.Signed();
        message.Value = reader.TailBytes(out _);
        return message;
    }
}

internal sealed class GetDistributedAsyncRequest : WireMessage
{
    internal static WireParser<GetDistributedAsyncRequest> Parser { get; } = new(Read);
    internal string CacheName { get; set; } = string.Empty;
    internal string Key { get; set; } = string.Empty;

    internal override void Encode(ref WireWriter writer)
    {
        writer.Text(CacheName);
        writer.Text(Key);
    }

    internal static GetDistributedAsyncRequest Read(ref WireReader reader)
    {
        var message = new GetDistributedAsyncRequest();
        message.CacheName = reader.Text(cacheName: true);
        message.Key = reader.Text();
        return message;
    }
}

internal sealed class BinaryCallError : WireMessage
{
    internal static WireParser<BinaryCallError> Parser { get; } = new(Read);
    internal string Detail { get; set; } = string.Empty;
    internal List<Types.Trailer> Trailers { get; } = [];

    internal override void Encode(ref WireWriter writer)
    {
        if (Detail.Length == 0 && Trailers.Count == 0)
            return;
        writer.Text(Detail);
        writer.ItemCount(Trailers.Count);
        foreach (var item in Trailers)
            item.Encode(ref writer);
    }

    internal static BinaryCallError Read(ref WireReader reader)
    {
        var message = new BinaryCallError();
        if (reader.Remaining == 0)
            return message;
        message.Detail = reader.Text();
        var count = reader.ItemCount();
        for (var i = 0; i < count; i++)
            message.Trailers.Add(Types.Trailer.Read(ref reader));
        return message;
    }

    internal static class Types
    {
        internal sealed class Trailer : WireMessage
        {
            internal static WireParser<Trailer> Parser { get; } = new(Read);
            internal string Key { get; set; } = string.Empty;
            internal enum ValueOneofCase : byte { None, Text, Binary }
            internal ValueOneofCase ValueCase { get; private set; }
            private string? _text;
            private ReadOnlyMemory<byte> _bytes;
            internal string Text
            {
                get => _text ?? string.Empty;
                set { _bytes = default; _text = value; ValueCase = ValueOneofCase.Text; }
            }
            internal ReadOnlyMemory<byte> Binary
            {
                get => ValueCase == ValueOneofCase.Binary ? _bytes : default;
                set { _text = null; _bytes = value; ValueCase = ValueOneofCase.Binary; }
            }

            internal override void Encode(ref WireWriter writer)
            {
                writer.Text(Key);
                writer.Byte((byte)ValueCase);
                switch (ValueCase)
                {
                    case ValueOneofCase.Text:
                        writer.Text(Text);
                        break;
                    case ValueOneofCase.Binary:
                        writer.Bytes(Binary);
                        break;
                }
            }

            internal static Trailer Read(ref WireReader reader)
            {
                var message = new Trailer();
                message.Key = reader.Text();
                switch ((ValueOneofCase)reader.Byte())
                {
                    case ValueOneofCase.None:
                        break;
                    case ValueOneofCase.Text:
                        message.Text = reader.Text();
                        break;
                    case ValueOneofCase.Binary:
                        message.Binary = reader.Bytes(out _);
                        break;
                    default:
                        throw new InvalidDataException("Unknown union discriminator.");
                }
                return message;
            }
        }
    }
}

internal sealed class RefreshDistributedAsyncRequest : CacheMutationRequest
{
    internal static WireParser<RefreshDistributedAsyncRequest> Parser { get; } = new(Read);
    internal string CacheName { get; set; } = string.Empty;
    internal string Key { get; set; } = string.Empty;

    internal override void Encode(ref WireWriter writer)
    {
        var operationId = writer.MutationOperationId ?? OperationId;
        writer.Byte((byte)((operationId.Length != 0 ? 1 : 0)));
        writer.Text(CacheName);
        writer.Text(Key);
        if (operationId.Length != 0)
            writer.OperationId(operationId);
    }

    internal static RefreshDistributedAsyncRequest Read(ref WireReader reader)
    {
        var message = new RefreshDistributedAsyncRequest();
        var flags = reader.Flags(1);
        message.CacheName = reader.Text(cacheName: true);
        message.Key = reader.Text();
        if ((flags & 1) != 0)
            message.OperationId = reader.OperationId();
        return message;
    }
}

internal sealed class RefreshDistributedAsyncResponse : WireMessage
{
    internal static WireParser<RefreshDistributedAsyncResponse> Parser { get; } = new(Read);
    internal static RefreshDistributedAsyncResponse Instance { get; } = new();
    internal static RefreshDistributedAsyncResponse Read(ref WireReader reader) => Instance;
    internal override void Encode(ref WireWriter writer) { }
}
